/*
 * i18n/locales/fr.js — Chaînes en français (isomorphe avec en.js / zh.js).
 *
 * Les clés manquantes retombent sur zh, puis sur la clé brute (voir index.js t).
 * Garder les clés synchronisées avec en.js (807 clés).
 *
 * Règles de traduction :
 * - cat.* / ui.* : traduits en français naturel.
 * - op.*.name : noms d'algorithmes de crypto/encodage internationaux conservés
 *   tels quels (Base64/MD5/AES/RSA/ROT13/SHA…), encodages chinois traduits par le sens.
 * - Les gabarits {0}/{1}… sont conservés à l'identique.
 */
