  "op.birthdayCollision.name": "Démo collision d'anniversaire",
  "op.birthdayCollision.desc": "Collision par anniversaire sur SHA-256 tronqué (bitLen bits, 2^(b/2) essais attendus) : une démonstration pédagogique de l'essence des collisions de hachage",

  "op.babaiCvp.name": "Babai Nearest Plane (CVP)",
  "op.babaiCvp.desc": "Réduction LLL + plan le plus proche de Babai : résolution approchée du problème du vecteur le plus proche (CVP) sur les réseaux (« vecteurs de base du réseau » : un vecteur de base par ligne ; « vecteur cible » : la cible)",

  "op.hnpRecover.name": "HNP Hidden Number Problem",
  "op.hnpRecover.desc": "Attaque par nonce faible ECDSA : quand les nonces des m signatures suivent k_i = t_i + x (x petit inconnu partagé), force brute sur x pour retrouver la clé privée d (entrée : h r s t par ligne)",

  "op.spnAnalysis.name": "SPN Differential/Linear Analysis",
  "op.spnAnalysis.desc": "Outil pédagogique : table de distribution des différentielles (DDT) et table d'approximation linéaire (LAT) des S-boxes 4 bits + caractéristiques différentielles/linéaires les plus fortes (S-box PRESENT par défaut)",

  "op.md5CollisionShow.name": "MD5 Truncated Collision Demo",
  "op.md5CollisionShow.desc": "Démonstration pédagogique : recherche de paires en collision par méthode des anniversaires sur MD5 tronqué (32 bits par défaut) — des entrées différentes partageant un hachage tronqué, pour montrer l'essence des collisions de hachage",

  "op.lweToy.name": "LWE Toy Encryption",
  "op.lweToy.desc": "Pédagogie post-quantique : démonstration de chiffrement/déchiffrement de bits Regev LWE (q=257, n=8) — pour comprendre le mécanisme de clé publique des réseaux (paramètres hors production)",

  "op.ntruToy.name": "NTRU Toy Encryption",
  "op.ntruToy.desc": "Pédagogie post-quantique : démonstration de chiffrement/déchiffrement sur l'anneau de polynômes tronqués NTRU (n=8, q=257, p=3) — pour comprendre le mécanisme NTRU (paramètres hors production)",
  "op.sha384.name": "SHA-384",
  "op.sha3.name": "SHA-3",
  "op.fnv1a.name": "FNV-1a",
