  "op.fletcher.name": "Fletcher",
  "op.fletcher.desc": "Somme de contrôle Fletcher (largeur 8/16/32/64 au choix ; 8 bits mod 15, 16 bits mod 255 sur le flot d'octets, 32 bits mod 65535 sur mots 16 bits petit-boutiste, 64 bits mod 2^32-1 sur mots 32 bits petit-boutiste). Mode d'entrée inputMode : auto (défaut ; hex pur de longueur paire décodé en octets, sinon UTF-8) / text (force UTF-8) / hex (force l'hexadécimal, erreur si invalide)",
