  "op.sm4.desc": "Chiffrement par blocs de la norme nationale chinoise (GB/T 32907-2016, anciennement GM/T 0002-2012 ; bloc 128 bits, clé 128 bits, 32 tours d'itération non linéaire. Modes : ECB/CBC/CFB/OFB/CTR + chiffrement authentifié GCM)",
