  "op.salsa20.desc": "Chiffrement de flux Salsa20/20 (Bernstein, key 16/32 octets, nonce 8 octets, compteur de blocs 64 bits)",
  "op.chacha20.name": "ChaCha20",
  "op.chacha20.desc": "Chiffrement de flux ChaCha20 (RFC 8439, key 32 octets, nonce 12 octets, compteur de blocs 32 bits)",
  "op.rc5.name": "RC5",
  "op.rc5.desc": "Chiffrement par blocs RC5-32/12/16 (RFC 2040, bloc 64 bits, 12 tours, clé variable ; prend en charge ECB/CBC/CFB/OFB/CTR)",
  "op.idea.name": "IDEA",
  "op.idea.desc": "Algorithme international de chiffrement des données (Lai 1991, bloc 64 bits, clé 128 bits, 8.5 tours, multiplication mod 2^16+1 + addition mod 2^16 + XOR)",
  "op.blowfish.name": "Blowfish",
  "op.blowfish.desc": "Chiffrement par blocs Blowfish (Schneier 1993, bloc 64 bits, clé variable 4-56 octets, Feistel 16 tours ; prend en charge ECB/CBC/CFB/OFB/CTR)",
  "op.rc6.name": "RC6",
  "op.rc6.desc": "Chiffrement par blocs RC6 (bloc 128 bits, clé variable 1-255 octets, 20 tours ; prend en charge ECB/CBC/CFB/OFB/CTR. Note : RFC 2276 n'est pas une norme RC6 ; RC6 n'a pas de RFC publique, voir l'article d'origine Rivest/Shamir/Yin)",
  "op.cast5.name": "CAST-128",
  "op.cast5.desc": "Chiffrement par blocs CAST-128/CAST5 (RFC 2144, bloc 64 bits, clé variable 5-16 octets, 12/16 tours ; prend en charge ECB/CBC/CFB/OFB/CTR)",
  "op.twofish.name": "Twofish",
  "op.twofish.desc": "Chiffrement par blocs Twofish (proposition AES 1998 de Schneier, bloc 128 bits, 16 tours, clé 128/192/256 bits ; prend en charge ECB/CBC/CFB/OFB/CTR)",
  "op.xorStrings.name": "XOR à Clé Cyclique",
  "op.xorStrings.desc": "XOR répété : le plus court du clair/de la clé boucle jusqu'à la longueur du plus long avant le XOR (auto-inverse)",

 // ---- op names (radix) ----
  "op.radixConvert.name": "Conversion de Base",
  "op.radixConvert.desc": "Conversion entre bases 2-36 arbitraires (BigInt, à l'abri du débordement)",
  "op.asciiRadix.name": "Caractère ↔ ASCII en Base",
  "op.asciiRadix.desc": "Caractères ↔ ASCII en chaque base (séquence d'octets UTF-8, largeur fixe séparée par espaces ; binaire : 7/8 bits, inversion 0-1, inversion d'ordre des bits)",
  "op.radixAll.name": "Convertisseur multibase",
  "op.radixAll.desc": "Une entrée, reniflée automatiquement (préfixes 0x/0b/0o / décimal / séparateurs), liste côte à côte les bases 2/8/10/16/32/36/62 + Base64 + octets numériques + unités de code UTF-16 + points de code Unicode + l'UTF-8 de ce point de code + la largeur en bits ; les négatifs donnent les compléments à deux 8/16/32/64 bits ; les ambiguïtés de chaînes tout-01 listent plusieurs lectures en parallèle. BigInt, aucune perte de précision pour les grands nombres.",
  "op.progCalc.name": "Calculatrice programmeur",
  "op.progCalc.desc": "Évaluateur d'expressions bit à bit (analyseur descendant récursif écrit à la main, sans eval) : & | ^ ~ << >> >>> + - * / % **, parenthèses, décalages circulaires rotl/rotr ; masques de mots 8/16/32/64 bits avec repli (BigInt partout), bascule signé/non signé ; sort en un coup décimal/hexadécimal/octal/binaire (groupes de 4 chiffres)/complément à deux/popcount/zéros de tête/zéros de queue.",
  "op.unitConv.name": "Convertisseur d'unités",
  "op.unitConv.desc": "Tailles de données B/KB/MB/GB/TB/PB en parallèle des KiB/MiB/GiB/TiB/PiB (SI 1000 vs IEC 60027-2 1024, tous les facteurs traçables) ; débits bps/Kbps/Mbps/Gbps ↔ B/s/KB/s/MB/s (bit×8) ; temps ns~d ; un nombre pur déclenche la comparaison d'époques d'horodatage (Unix s/ms, FILETIME, Cocoa, Chrome μs, DOS empaqueté, magnitude reniflée automatiquement) ; fréquence Hz~GHz ; angles deg/rad/gon. Les tailles de données utilisent des rationnels BigInt de bout en bout — zéro perte de précision à l'échelle du PB, décimales exactes et troncatures clairement marquées.",
  "op.ieee754.name": "Flottant IEEE754",
  "op.ieee754.desc": "Flottant ↔ hexadécimal (demi/simple/double précision)",
  "op.bcd.name": "BCD",
  "op.bcd.desc": "Chaîne de chiffres décimaux ↔ chaîne hex BCD",
  "op.binPad.name": "Remplissage de Zéros Binaire",
  "op.binPad.desc": "Nombre décimal → chaîne binaire à largeur fixe (complétée de zéros)",
