 // ---- education card ----
  "ui.edu.title": "Explication & Exemples",
  "ui.edu.what": "Qu'est-ce que c'est",
  "ui.edu.principle": "Comment ça marche",
  "ui.edu.usage": "Comment l'utiliser",
  "ui.edu.formula": "Formule",
  "ui.edu.example": "Exemples",
  "ui.edu.exIn": "Entrée",
