  "op.columnReplace.name": "Transposition de Colonnes",
  "op.columnReplace.desc": "Lit les colonnes dans l'ordre alphabétique de la clé (clair complété d'espaces jusqu'à un multiple de keylen)",
  "op.rowsReplace.name": "Transposition de Lignes",
  "op.rowsReplace.desc": "Tous les keylen caractères forment un bloc, réordonné dans le bloc selon l'ordre alphabétique de la clé",
