  "ui.about.intro": "Une boîte à outils CTF purement front-end de codage, de cryptographie et de stéganographie — plus de 500 opérations couvrant codage / chiffrements classiques et modernes / hachage / stéganographie / criminalistique / analyse. Tout s'exécute localement dans votre navigateur : sans réseau, sans envoi, sans trace. Déployez-la en ouvrant directement index.html, en lançant un serveur local ou en l'hébergeant comme site statique.",
