  "ui.rand.warnCustom": "⚠ Ce mode dépend entièrement du caractère aléatoire que vous fournissez. Si la source est prévisible, les clés et signatures produites peuvent être reproduites par autrui. Ne l'utilisez que si vous savez précisément ce que vous faites.",
  "ui.rand.warnServer": "Une fois activé, cet outil enverra des requêtes réseau à l'adresse que vous indiquez pour obtenir des nombres aléatoires ; c'est vous qui l'avez configuré : ce projet ne relaie pas, n'enregistre pas et ne préconfigure aucun serveur.",
  "ui.rand.workerNote": "Hors mode système, les opérations concernées s'exécutent de force sur le thread principal, pour éviter qu'un thread d'arrière-plan, privé de votre entropie, ne retombe silencieusement sur la source système.",
