  "ui.rand.mouseAuxDesc": "Collectez de l'entropie locale en agitant la souris dans la fenêtre ; elle s'ajoute au mode courant (seulement en plus, le résultat n'est jamais plus faible que ce mode). Pour les systèmes non fiables : la source système cesse d'être un point unique.",
