  "op.randomSecure.name": "Sécurité aléatoire renforcée",
  "op.randomSecure.desc": "Consulter / changer le mode de source aléatoire, consulter son état, obtenir des nombres aléatoires d'une longueur donnée (hex / base64)",
  "op.randBeacon.name": "Vérification de balise aléatoire publique",
  "op.randBeacon.desc": "Vérifie les balises aléatoires publiques drand / NIST : recalcul hors ligne à partir de la signature officielle (BLS12-381 / RSA) et de la structure chaînée, prouvant qu'un enregistrement est authentique et non altéré. L'intérêt est la « vérifiabilité publique et l'immuabilité a posteriori », pas le « plus aléatoire » ; ce n'est pas une source de clés, totalement isolée de la génération de clés. Aucune requête réseau par défaut, uniquement sur récupération explicite de l'utilisateur.",
  "ui.about.langs": "Langues prises en charge",
  "ui.about.langsNote": "Complétude de la traduction de l'interface (mesurée par rapport à la table source chinoise, calculée à l'ouverture de cette page ; les entrées manquantes reviennent au chinois)",
  "op.caesar.desc": "Décalage fixe (encode +shift, decode -shift) ; le mode bascule vers un César progressif (le caractère x est décalé de shift±x) ; le jeu de caractères bascule entre lettres seules et ASCII imprimable 33-126 en entier (pour les variantes où les non-lettres bougent aussi)",
  "op.spriteSheet.name": "Conversion de spritesheet",
  "op.spriteSheet.desc": "Spritesheet ↔ séquence de frames : split découpe une grille N×M en PNG par frame (ordre ligne par ligne, frame_000 onwards) ; merge assemble des frames (première frame en entrée principale + un dataURL par ligne dans les extras) en grille selon les frames par ligne, cellules vintes transparentes. PNG en pur JS, partout disponible",
  "ui.op.pendingRun": "[{0}] est prêt mais non exécuté automatiquement.\nCliquez sur le bouton Convertir ci-dessous pour lancer.",
